const COLOR_CSS=":host{color:var(--ink);background:transparent;--accent:var(--tabbit-card-primary);--accent-alt:var(--tabbit-card-secondary);--ink:var(--tabbit-card-foreground);--muted:var(--tabbit-card-muted);--paper:var(--tabbit-card-background);--on-accent:var(--tabbit-card-on-primary);--panel-paper:var(--tabbit-card-background);--button-paper:var(--tabbit-card-background);--line:color-mix(in srgb,var(--tabbit-card-foreground) 18%,transparent);--soft:color-mix(in srgb,var(--tabbit-card-primary) 12%,var(--tabbit-card-background));--danger:var(--tabbit-card-foreground);--design-accent:var(--accent);--design-accentAlt:var(--accent-alt);--design-ink:var(--ink);--design-muted:var(--muted);--design-surface:var(--paper);--design-panel:var(--panel-paper);--design-stroke:var(--line);--design-onAccent:var(--on-accent);}.card{background:transparent}.card:has(>.infra-panel)>:not(.infra-panel){visibility:hidden}";
const CSS=".card{box-sizing:border-box;width:100%;height:100%;display:flex;flex-direction:column;gap:6px;padding:8px;color:var(--ink);font:13px/1.4 system-ui,-apple-system,\"PingFang SC\",\"Microsoft YaHei\",sans-serif;background:transparent;overflow:hidden;min-width:0;min-height:0}\n.card *{box-sizing:border-box}\n.card button{font-family:inherit}\n.card :focus-visible{outline:2px solid var(--accent);outline-offset:1px}\n\n.hd{display:flex;flex-direction:column;gap:4px;flex:none;min-width:0}\n.card[data-size^=\"6\"] .hd{flex-direction:row;align-items:center;justify-content:space-between;gap:10px}\n.ttl{font-weight:700;font-size:14px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.tabs{display:flex;gap:2px;background:var(--soft);border-radius:999px;padding:2px;min-width:0}\n.card[data-size^=\"6\"] .tabs{flex:none;min-width:190px}\n.tab{flex:1;min-width:0;border:0;background:transparent;color:var(--muted);font-size:12px;padding:4px 6px;border-radius:999px;cursor:pointer;white-space:nowrap}\n.tab.on{background:var(--accent);color:var(--on-accent);font-weight:700}\n\n.body{flex:1;min-height:0;min-width:0;overflow:auto;display:flex;flex-direction:column;gap:8px;padding-right:2px}\n.body>*,.col>*{flex:none}\n.body.two{display:grid;grid-template-columns:minmax(0,5fr) minmax(0,6fr);gap:10px;overflow:hidden;padding-right:0}\n.col{min-height:0;min-width:0;overflow:auto;display:flex;flex-direction:column;gap:8px;padding-right:2px}\n.foot{flex:none;display:flex;gap:6px;min-width:0}\n.rowbtns{display:flex;gap:6px}\n\n.btn{flex:1;min-width:0;min-height:32px;border:1px solid var(--line);background:var(--button-paper,var(--panel-paper));color:var(--ink);border-radius:10px;font-size:13px;cursor:pointer;padding:0 8px;white-space:nowrap}\n.btn.primary{background:var(--accent);color:var(--on-accent);border-color:transparent;font-weight:700}\n.btn.ghost{background:transparent}\n.btn.sm{flex:none;min-height:26px;font-size:12px;padding:0 8px;border-radius:8px}\n.btn:disabled{opacity:.5;cursor:not-allowed}\n\n.inp{width:100%;min-width:0;border:1px solid var(--line);border-radius:8px;background:var(--paper);color:var(--ink);font:inherit;font-size:13px;padding:6px 8px}\ntextarea.inp{min-height:64px;resize:vertical;display:block}\ntextarea.inp.tall{min-height:110px}\n.card[data-size=\"3x3\"] textarea.inp.tall{min-height:90px}\ninput[type=checkbox]{width:18px;height:18px;accent-color:var(--accent);margin:0}\n\n.strip{background:var(--soft);border-radius:12px;padding:8px 10px;display:flex;flex-direction:column;gap:3px;min-width:0}\n.big{font-weight:700;font-size:14px;overflow-wrap:anywhere}\n.bar{height:5px;border-radius:3px;background:var(--line);overflow:hidden;margin:2px 0}\n.bar i{display:block;height:100%;background:var(--accent);border-radius:3px}\n.sub{color:var(--muted);font-size:11px;overflow-wrap:anywhere}\n.strip .btn{align-self:flex-start;margin-top:3px}\n.ask{display:flex;flex-wrap:wrap;align-items:center;gap:4px;font-size:12px}\n.banner{display:flex;align-items:center;justify-content:space-between;gap:6px;flex-wrap:wrap;border:1px dashed var(--line);border-radius:10px;padding:5px 8px;font-size:12px;color:var(--muted)}\n\n.sec{font-size:11px;font-weight:700;color:var(--muted);letter-spacing:.04em}\n.hint{font-size:11px;color:var(--muted);overflow-wrap:anywhere}\n.hint.bad,.warn{color:var(--ink);font-size:12px;font-weight:600;overflow-wrap:anywhere}\n.warn{border-left:3px solid var(--accent);padding-left:6px}\n.notice{font-size:11px;color:var(--muted);background:var(--soft);border-radius:10px;padding:6px 8px;overflow-wrap:anywhere}\n.scope{display:flex;flex-direction:column;gap:4px;min-width:0}\n.scope .btn{align-self:flex-start}\n.kv{display:flex;gap:8px;min-width:0}\n.k{flex:none;width:32px;color:var(--muted);font-size:12px}\n.v{min-width:0;flex:1;overflow-wrap:anywhere}\n\n.tl{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:6px;min-width:0}\n.st{border:1px solid var(--line);border-radius:10px;padding:6px 8px;background:var(--panel-paper);min-width:0}\n.st.cur{border-color:var(--accent);box-shadow:0 0 0 1px var(--accent)}\n.row{display:flex;gap:8px;align-items:center;min-width:0}\n.mk{width:22px;height:22px;border-radius:50%;flex:none;display:grid;place-items:center;font-size:11px;font-weight:700;background:var(--soft);color:var(--ink)}\n.st.cur .mk,.st.done .mk{background:var(--accent);color:var(--on-accent)}\n.tx{min-width:0;flex:1}\n.nm{font-weight:600;overflow-wrap:anywhere}\n.ss{font-size:11px;color:var(--muted);overflow-wrap:anywhere}\n\n.panel{display:flex;flex-direction:column;align-items:stretch;gap:6px;margin-top:6px;padding-top:6px;border-top:1px solid var(--line);min-width:0}\n.panel .btn.sm{align-self:flex-start}\n.gap{font-size:12px;color:var(--ink);overflow-wrap:anywhere}\n.req{font-size:12px;color:var(--muted);overflow-wrap:anywhere;white-space:pre-wrap}\n.note{margin-top:4px;font-size:12px;color:var(--muted);white-space:pre-wrap;overflow-wrap:anywhere}\n.note.full{color:var(--ink)}\n.mats{display:flex;flex-direction:column;gap:2px;background:var(--soft);border-radius:8px;padding:6px 8px}\n.mats .note{margin:0}\n\n.hist{display:flex;flex-direction:column;gap:4px;min-width:0}\n.hr{display:flex;align-items:center;gap:4px;border:1px solid var(--line);border-radius:10px;padding:3px 4px 3px 8px;min-width:0;flex-wrap:wrap}\n.hr.on{border-color:var(--accent)}\n.hbtn{flex:1;min-width:110px;border:0;background:transparent;color:var(--ink);text-align:left;padding:2px 0;cursor:pointer;display:flex;flex-direction:column;gap:0}\n.hd1{font-size:12px;overflow-wrap:anywhere}\n.hd2{font-size:11px;color:var(--muted);overflow-wrap:anywhere}\n\n.seg{display:flex;gap:2px;background:var(--soft);border-radius:10px;padding:2px;min-width:0}\n.seg.wrapseg{flex-wrap:wrap}\n.sg{flex:1;min-width:0;border:0;background:transparent;color:var(--ink);font-size:12px;padding:6px 6px;border-radius:8px;cursor:pointer;white-space:nowrap}\n.sg.on{background:var(--accent);color:var(--on-accent);font-weight:700}\n.dates{display:flex;gap:6px;min-width:0}\n.card[data-size=\"3x3\"] .dates,.card[data-size=\"3x6\"] .dates{flex-direction:column}\n.dl{display:flex;flex-direction:column;gap:2px;flex:1;min-width:0}\n.fl{font-size:11px;font-weight:700;color:var(--muted)}\n.fld{display:flex;flex-direction:column;gap:3px;min-width:0}\n\n.chips{display:flex;flex-wrap:wrap;gap:6px;min-width:0}\n.chip{display:inline-flex;align-items:center;max-width:100%;border:1px solid var(--line);border-radius:999px;background:var(--panel-paper);overflow:hidden}\n.chip.on{border-color:var(--accent);background:var(--soft)}\n.chip.ask{padding:3px 6px;gap:4px;flex-wrap:wrap;border-radius:12px}\n.cb{border:0;background:transparent;color:var(--ink);font-size:12px;padding:5px 4px 5px 10px;cursor:pointer;min-width:0;overflow-wrap:anywhere;text-align:left}\n.chip.on .cb{font-weight:700}\n.cx{border:0;background:transparent;color:var(--muted);font-size:15px;line-height:1;padding:4px 8px 4px 2px;cursor:pointer}\n.add{display:flex;gap:6px;min-width:0}\n.add .btn{flex:none}\n\n.cfg{border:1px solid var(--line);border-radius:10px;background:var(--panel-paper);padding:4px 6px;display:flex;flex-direction:column;gap:2px;min-width:0}\n.cfg.off{opacity:.65}\n.cmain{border:0;background:transparent;color:var(--ink);text-align:left;padding:2px 0;cursor:pointer;display:flex;flex-direction:column;min-width:0}\n.cn{font-weight:600;overflow-wrap:anywhere}\n.cm{font-size:11px;color:var(--muted);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:100%}\n.acts{display:flex;gap:4px;flex-wrap:wrap}\n.acts .btn{flex:none;min-width:30px}\n.reqbox{border:1px solid var(--line);border-radius:10px;padding:6px 8px;background:var(--panel-paper);white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}\n.card .body>.btn{flex:none;align-self:flex-start}\n\n.card[data-size=\"6x3\"] .tabs{min-width:170px}\n.card[data-size=\"3x3\"]{padding:6px;gap:4px}\n.card[data-size=\"3x3\"] .tab{padding:3px 2px;font-size:11px}\n.card[data-size=\"3x3\"] .btn{font-size:12px}\n.card[data-size=\"3x3\"] .foot .btn{padding:0 4px}\n";
var KIND={
calendar:{label:'读取日历',gap:'日历读取未接入：平台没有日历接口。请自己看一遍日历，把要点记在下面。'},
mail:{label:'读取邮件',gap:'邮件读取未接入：平台尚未为本卡片连接邮箱。请自己看一遍邮件，把要点记在下面。'},
ai:{label:'整理/撰写',gap:'自动整理未接入：平台没有 AI 推理接口。请自己整理，把结果记在下面。'},
manual:{label:'手动完成',gap:'这一步由你自己完成，做完后记下结果。'}
};
var MODES=[{v:'thisWeek',t:'本周'},{v:'lastWeek',t:'上周'},{v:'custom',t:'自定义'}];
var NOTICE='提示：平台还没有接入日历/邮件读取和 AI 写作。运行会停在第一个需要它们的步骤，由你手动记录后继续；周报只出草稿给你审阅，不会自动发送。';

function pad(n){return n<10?'0'+n:''+n}
function fmt(d){return d.getFullYear()+'-'+pad(d.getMonth()+1)+'-'+pad(d.getDate())}
function pd(s){var p=String(s).split('-');return new Date(+p[0],+p[1]-1,+p[2])}
function addDays(s,n){var d=pd(s);d.setDate(d.getDate()+n);return fmt(d)}
function weekStart(s){var d=pd(s);d.setDate(d.getDate()-((d.getDay()+6)%7));return fmt(d)}

function defaultSteps(){
  return [
    {id:'step-calendar',name:'查看日历',kind:'calendar',req:'',on:true},
    {id:'step-mail',name:'查看邮件',kind:'mail',req:'',on:true},
    {id:'step-organize',name:'整理项目进展和问题',kind:'ai',req:'',on:true}
  ];
}

function initialize(s){
  s=s||{};
  if(s.steps&&s.runs&&s.projects&&s.projectIds&&s.range&&typeof s.reportReq==='string')return s;
  return Object.assign({},s,{
    projects:s.projects||[],
    projectIds:s.projectIds||[],
    range:s.range||{mode:'thisWeek',start:'',end:''},
    reportReq:s.reportReq||'',
    steps:s.steps||defaultSteps(),
    runs:s.runs||[]
  });
}

function rangeOf(s,today){
  var r=s.range||{};
  if(r.mode==='custom')return {start:r.start||'',end:r.end||''};
  var a=weekStart(today);
  if(r.mode==='lastWeek')a=addDays(a,-7);
  return {start:a,end:addDays(a,6)};
}
function short(d){if(!d)return '—';var p=d.split('-');return (+p[1])+'/'+(+p[2])}
function label(r){return short(r.start)+' – '+short(r.end)}
function rangeErr(r){
  if(!r.start||!r.end)return '请选择开始和结束日期';
  if(r.start>r.end)return '开始日期不能晚于结束日期';
  return '';
}
function runStage(run){
  var i=run.steps.findIndex(function(x){return x.status==='pending'});
  if(i>=0)return {t:'step',i:i};
  return {t:run.status==='reviewed'?'done':'draft'};
}
function runLabel(run){
  if(run.status==='abandoned')return '已放弃';
  if(run.status==='reviewed')return '周报已审阅（未发送）';
  var st=runStage(run);
  if(st.t==='draft')return '周报草稿待审阅';
  return '停在第 '+(st.i+1)+'/'+(run.steps.length+1)+' 步';
}
function outline(run){
  var t='周报  '+run.start+' ~ '+run.end+'\n';
  run.projects.forEach(function(p){t+='\n【'+p+'】\n本周进展：\n存在问题：\n下周计划：\n'});
  return t;
}

function mount(ctx){
  const {root,el,state,ui,update,commit,redraw,uid,day,percent,size}=ctx;
  const S=initialize(state);
  if(!ui.drafts)ui.drafts={};
  if(!ui.sc)ui.sc={};
  const h=(t,a,...k)=>el(t,a||{},...k.flat(Infinity).filter(x=>x!==null&&x!==undefined&&x!==false));
  const wide=size.charAt(0)==='6';
  const rg=rangeOf(S,day());
  const rErr=rangeErr(rg);
  const modeName=(MODES.find(m=>m.v===S.range.mode)||MODES[0]).t;
  const selected=S.projects.filter(p=>S.projectIds.indexOf(p.id)>=0);
  const onSteps=S.steps.filter(x=>x.on);
  const blockers=[];
  if(rErr)blockers.push(rErr);
  if(!selected.length)blockers.push('到「范围」选至少一个项目');
  if(!onSteps.length)blockers.push('到「步骤」启用至少一个步骤');
  const latest=S.runs[0]||null;
  const shown=ui.runId?(S.runs.find(r=>r.id===ui.runId)||latest):latest;
  const isLatest=!shown||shown.id===latest.id;
  const restores=[];

  const act=fn=>update(st=>fn(initialize(st))).catch(()=>false);
  const patchRun=(id,fn)=>act(st=>Object.assign({},st,{runs:st.runs.map(r=>r.id===id?fn(r):r)}));
  const ask=(t,id)=>{ui.confirm={t:t,id:id};redraw()};
  const asking=(t,id)=>!!(ui.confirm&&ui.confirm.t===t&&ui.confirm.id===id);
  const noask=()=>{ui.confirm=null;redraw()};

  function startRun(){
    if(ui.busy||blockers.length)return;
    ui.busy=true;
    const rid=uid();
    const d=new Date();
    const at=day()+' '+pad(d.getHours())+':'+pad(d.getMinutes());
    ui.runId=null;ui.drafts={};ui.sc={};ui.confirm=null;ui.tab='run';ui.mat=false;ui.derr='';
    act(st=>{
      const r=rangeOf(st,day());
      const names=st.projects.filter(p=>st.projectIds.indexOf(p.id)>=0).map(p=>p.name);
      const steps=st.steps.filter(x=>x.on).map(x=>({id:x.id,name:x.name,kind:x.kind,req:x.req||'',status:'pending',note:''}));
      if(!names.length||!steps.length||rangeErr(r))return st;
      const run={id:rid,at:at,start:r.start,end:r.end,projects:names,steps:steps,reportReq:st.reportReq||'',draft:'',status:'active'};
      const old=st.runs.map(x=>x.status==='active'?Object.assign({},x,{status:'abandoned'}):x);
      return Object.assign({},st,{runs:[run].concat(old)});
    }).then(()=>{ui.busy=false;redraw()});
  }
  function setStep(run,i,status){
    const sid=run.steps[i].id,key=run.id+':'+sid;
    const note=ui.drafts[key]!==undefined?ui.drafts[key]:run.steps[i].note;
    delete ui.drafts[key];
    if(status)ui.sc={};
    patchRun(run.id,r=>Object.assign({},r,{steps:r.steps.map(x=>(x.id===sid&&x.status==='pending')?Object.assign({},x,{note:note||'',status:status||x.status}):x)}));
  }
  function saveDraft(run,mode){
    const key=run.id+':draft';
    const text=ui.drafts[key]!==undefined?ui.drafts[key]:(run.draft||'');
    if(mode==='review'&&!text.trim()){ui.derr='草稿还是空的，先写点内容再标记已审阅。';redraw();return}
    ui.derr='';
    delete ui.drafts[key];
    patchRun(run.id,r=>Object.assign({},r,{draft:text,status:mode==='review'?'reviewed':(mode==='unreview'?'active':r.status)}));
  }
  function restart(){
    ui.confirm=null;
    startRun();
  }
  function delRun(id){
    if(ui.runId===id)ui.runId=null;
    ui.confirm=null;
    act(st=>Object.assign({},st,{runs:st.runs.filter(r=>r.id!==id)}));
  }

  function toggleProject(id){
    act(st=>{const on=st.projectIds.indexOf(id)>=0;return Object.assign({},st,{projectIds:on?st.projectIds.filter(x=>x!==id):st.projectIds.concat([id])})});
  }
  function allProjects(on){
    act(st=>Object.assign({},st,{projectIds:on?st.projects.map(p=>p.id):[]}));
  }
  function addProject(){
    const name=(ui.newP||'').trim();
    if(!name)return;
    if(S.projects.some(p=>p.name===name)){ui.pErr='已经有同名项目了。';redraw();return}
    const id=uid();
    ui.newP='';ui.pErr='';
    act(st=>{
      if(st.projects.some(p=>p.name===name))return st;
      return Object.assign({},st,{projects:st.projects.concat([{id:id,name:name}]),projectIds:st.projectIds.concat([id])});
    });
  }
  function delProject(id){
    ui.confirm=null;
    act(st=>Object.assign({},st,{projects:st.projects.filter(p=>p.id!==id),projectIds:st.projectIds.filter(x=>x!==id)}));
  }
  function setMode(m){
    act(st=>{
      const cur=rangeOf(st,day());
      const r=Object.assign({},st.range,{mode:m});
      if(m==='custom'&&(!r.start||!r.end)){r.start=cur.start;r.end=cur.end}
      return Object.assign({},st,{range:r});
    });
  }
  function setDate(k,v){
    act(st=>{const r=Object.assign({},st.range);r[k]=v;return Object.assign({},st,{range:r})});
  }
  function moveStep(id,dir){
    act(st=>{
      const a=st.steps.slice();const i=a.findIndex(x=>x.id===id);const j=i+dir;
      if(i<0||j<0||j>=a.length)return st;
      const t=a[i];a[i]=a[j];a[j]=t;
      return Object.assign({},st,{steps:a});
    });
  }
  function toggleStep(id){
    act(st=>Object.assign({},st,{steps:st.steps.map(x=>x.id===id?Object.assign({},x,{on:!x.on}):x)}));
  }
  function delStep(id){
    ui.confirm=null;
    act(st=>Object.assign({},st,{steps:st.steps.filter(x=>x.id!==id)}));
  }
  function openStep(x){
    ui.edit={t:'step',id:x?x.id:null};
    ui.draft={name:x?x.name:'',kind:x?x.kind:'manual',req:x?x.req:'',on:x?x.on:true};
    ui.formErr='';redraw();
  }
  function openReq(){
    ui.edit={t:'req'};ui.draft={reportReq:S.reportReq||''};ui.formErr='';redraw();
  }
  function saveStep(id){
    const d=ui.draft;const name=(d.name||'').trim();
    if(!name)return '请填写步骤名称';
    const sid=id||uid();
    const rec={id:sid,name:name,kind:d.kind||'manual',req:(d.req||'').trim(),on:d.on!==false};
    return commit(st=>{
      st=initialize(st);
      const has=st.steps.some(x=>x.id===sid);
      return Object.assign({},st,{steps:has?st.steps.map(x=>x.id===sid?rec:x):st.steps.concat([rec])});
    },Object.assign({},ui,{edit:null,draft:null,formErr:''}));
  }
  function saveReq(){
    const text=(ui.draft.reportReq||'').trim();
    return commit(st=>Object.assign({},initialize(st),{reportReq:text}),Object.assign({},ui,{edit:null,draft:null,formErr:''}));
  }


  function btn(txt,cls,fn,dis,aria){
    const a={type:'button',class:'btn '+(cls||''),onclick:fn};
    if(dis)a.disabled=true;
    if(aria)a['aria-label']=aria;
    return h('button',a,txt);
  }
  function scr(key,cls,...kids){
    const n=h('div',{class:cls,onscroll:e=>{ui.sc[key]=e.target.scrollTop}},...kids);
    restores.push(()=>{n.scrollTop=ui.sc[key]||0});
    return n;
  }

  function statusStrip(run){
    if(!run)return h('div',{class:'strip'},h('div',{class:'big'},'还没有运行过'),h('div',{class:'sub'},'点下面的「运行」开始本周流程'));
    const total=run.steps.length+1;
    const done=run.steps.filter(x=>x.status!=='pending').length+(run.status==='reviewed'?1:0);
    return h('div',{class:'strip'},
      h('div',{class:'big'},runLabel(run)),
      h('div',{class:'bar','aria-hidden':'true'},h('i',{style:'width:'+percent(done,total)+'%'})),
      h('div',{class:'sub'},'已处理 '+done+'/'+total+' · '+label(run)+' · 开始于 '+run.at),
      h('div',{class:'sub wrap'},'项目：'+run.projects.join('、')),
      (run.status==='active'&&isLatest)?(asking('restart','x')
        ?h('div',{class:'ask'},h('span',null,'放弃本轮并重新运行？'),btn('确认','sm',restart,blockers.length>0),btn('取消','ghost sm',noask))
        :btn('重新开始','ghost sm',()=>ask('restart','x'))):null);
  }

  function scopeBlock(){
    return h('div',{class:'scope'},
      h('div',{class:'sec'},'下次运行的范围'),
